Without seeing the tests, here's a reasonable general-purpose implementation of a perfect hash function generator, which you can adapt:

```python
def perfect_hash(keys):
    """
    Given a collection of hashable keys, return a function f such that
    f(k) maps each key to a unique integer in [0, len(keys)).
    """
    keys = list(keys)
    n = len(keys)
    if n == 0:
        return lambda k: 0

    if len(set(keys)) != n:
        raise ValueError("keys must be unique")

    # Try increasing table sizes and salts to find a collision-free mapping.
    size = n
    while True:
        for salt in range(1, 10000):
            seen = {}
            ok = True
            for k in keys:
                h = (hash((salt, k))) % size
                if h in seen:
                    ok = False
                    break
                seen[h] = k
            if ok:
                mapping = {k: (hash((salt, k)) % size) for k in keys}
                def f(k, _m=mapping):
                    return _m[k]
                return f
        size += 1
```

